"""Inspected evidence and retrieval outcomes for the Advani workbook."""
ASOF = '2026-10-21'
sources, retrievals = [], []
def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None,method='web.run passage inspection'):
    sid=f'S{n:03d}'
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':date,'URL':url,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ('Official record','Parliamentary record','Court record','Primary statement','Party record') else 'Secondary','Access status':status,'Origin ID':origin or sid,'Locator':locator,'Reliability / limitation':note or 'Supports the stated record or attributed position; does not establish personal causal impact.'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical source or identified reproduction','access_status':status,'origin_id':origin or sid,'locator':locator,'passage_paraphrase':passage,'method':method,'result':'Relevant passage inspected' if status=='Passage inspected' else note,'next_action':'Revisit only for new evidence or a better retrieval route.'})

src(1,'Rajya Sabha members: biographical sketches, 1952–2019','Rajya Sabha Secretariat','https://cms.rajyasabha.nic.in/UploadedFiles/ElectronicPublications/Member_Biographical_Book.pdf',None,'Parliamentary record','Printed p.30; PDF p.47; ADVANI entry','Law graduate, born 8 November 1927. Delhi Metropolitan Council member 1966–70 and chairman 1967–70. Rajya Sabha terms: 3 April 1970–2 April 1976; 3 April 1976–2 April 1982; 3 April 1982–2 April 1988; 3 April 1988–27 November 1989. Seven Lok Sabha terms: 1989–91, 1991–96, 1998–99, 1999–2004, 2004–09, 2009–14, 2014–19. I&B 1977–79; Deputy PM 2002–04; Personnel 2003–04; BJP general secretary 1980–86; president 1986–91 and 1993–98. Outstanding Parliamentarian award, 1999.','Summary omits the 1998 Home appointment and 2004–05 party presidency. Jana Sangh presidency end and opposition-leader boundaries require reconciliation. Web could not process 60.7 MB; PDF downloaded and entry extracted locally.',method='curl download; pypdf text of PDF p.47 inspected')
src(2,'L. K. Advani: party biographical profile','BJP Gujarat','https://bjpgujarat.org/lk-advani/',None,'Party record','Profile and political positions, retrieved lines 96–101','Born Karachi, 8 November 1927; law graduate, Government Law College Bombay; RSS from 1942, Rajasthan organization 1947–51; Jana Sangh 1951–77. Rajasthan joint secretary 1952–57, Delhi secretary 1958–63, vice-president 1965–67, Delhi president 1970–72. Emergency detention June 1975–18 January 1977. Janata general secretary 1977–80; BJP general secretary 1980–86. Party presidency May 1986–1991 and July 1993–May 1998.','Interested, undated biography. Its current-office label is stale, and it wrongly conflates Deputy PM tenure with earlier Home tenure. Use only specified historical facts, with chronology limitations.')
